solution:
def review(rows, target, start, run):
    matches = [r for r in rows if r.get('Id') == target]
    if len(matches) != 1:
        return None
    r = matches[0]
    if r.get('start') != start or r.get('run') != run:
        return None
    return {'Id':target,'decision':'review'}
